/**
 * How much script each route makes a browser load, and what it is made of.
 *
 *   node scripts/route-script.mjs http://127.0.0.1:3031 [/ /builder /site ...] [--json out.json] [--modules]
 *
 * Opens each route in headless Chromium, waits for the network to go quiet,
 * and adds up every JavaScript response: decoded bytes (what the browser
 * parses) and bytes on the wire (what `next start` sent, compressed). A
 * script loaded later, by a click, is not counted: this is first load.
 *
 * `--modules` also splits each route's bytes by source file, which needs a
 * build made with browser source maps:
 *
 *   POLIO_SOURCEMAPS=1 npm run build
 *
 * Source files are grouped by package (`node_modules/three`) or by folder
 * under `src/` two levels deep, so the table says what to cut.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { chromium } from "playwright-core";

const args = process.argv.slice(2);
const base = (args.find((a) => /^https?:/.test(a)) ?? "http://127.0.0.1:3031").replace(/\/$/, "");
const jsonAt = args.includes("--json") ? args[args.indexOf("--json") + 1] : null;
const withModules = args.includes("--modules") || args.includes("--files");
/* `--files`: one line per source file instead of per folder, for an import-graph tool to weigh. */
const perFile = args.includes("--files");
const routes = args.filter((a) => a.startsWith("/") && a !== jsonAt);
if (!routes.length) routes.push("/", "/builder", "/site");

const AT = process.env.PLAYWRIGHT_CHROMIUM;
const browser = await chromium.launch({ args: ["--disable-gpu", "--use-angle=swiftshader", "--in-process-gpu"], ...(AT ? { executablePath: AT } : {}) });

/** One route's scripts: [{ url, decoded, wire, first }]; `first` is a script the HTML itself names, which the page waits for before it can draw. */
async function scriptsOf(route) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  const cdp = await ctx.newCDPSession(page);
  await cdp.send("Network.enable");
  const byId = new Map();
  const fromHtml = new Set();
  cdp.on("Network.requestWillBeSent", (e) => { if (e.initiator?.type === "parser") fromHtml.add(e.requestId); });
  cdp.on("Network.responseReceived", (e) => { if (e.type === "Script") byId.set(e.requestId, { url: e.response.url, decoded: 0, wire: 0, first: fromHtml.has(e.requestId) }); });
  cdp.on("Network.dataReceived", (e) => { const s = byId.get(e.requestId); if (s) s.decoded += e.dataLength; });
  cdp.on("Network.loadingFinished", (e) => { const s = byId.get(e.requestId); if (s) s.wire = e.encodedDataLength; });
  await page.goto(base + route, { waitUntil: "networkidle", timeout: 120_000 });
  await page.waitForTimeout(1500);
  await ctx.close();
  return [...byId.values()].filter((s) => s.url.startsWith(base));
}

/* Source-map attribution: generated bytes of a chunk, per original source. */
const chunkDir = join(process.cwd(), ".next");
const mapCache = new Map();
async function modulesOf(url) {
  const path = new URL(url).pathname.replace(/^\/_next\//, "");
  const file = join(chunkDir, path);
  if (mapCache.has(file)) return mapCache.get(file);
  const out = new Map();
  mapCache.set(file, out);
  if (!existsSync(file)) return out;
  const code = readFileSync(file, "utf8");
  const ref = code.match(/\/\/# sourceMappingURL=(\S+)\s*$/);
  if (!ref) return out;
  const mapFile = join(file, "..", ref[1]);
  if (!existsSync(mapFile)) return out;
  const { SourceMapConsumer } = await import("source-map-js");
  const raw = JSON.parse(readFileSync(mapFile, "utf8"));
  const sections = raw.sections ?? [{ offset: { line: 0, column: 0 }, map: raw }];
  const lines = code.split("\n");
  /* Every mapping's start, in generated order, then each owns the bytes up to the next. */
  const starts = [];
  for (const s of sections) {
    const c = new SourceMapConsumer(s.map);
    c.eachMapping((m) => {
      const line = m.generatedLine - 1 + s.offset.line;
      const col = (m.generatedLine === 1 ? s.offset.column : 0) + m.generatedColumn;
      starts.push({ line, col, src: m.source ?? "(none)" });
    }, null, SourceMapConsumer.GENERATED_ORDER);
  }
  starts.sort((a, b) => a.line - b.line || a.col - b.col);
  for (let i = 0; i < starts.length; i++) {
    const a = starts[i], b = starts[i + 1];
    const end = b && b.line === a.line ? b.col : lines[a.line]?.length ?? a.col;
    const n = Buffer.byteLength(lines[a.line]?.slice(a.col, end) ?? "");
    const key = group(a.src);
    out.set(key, (out.get(key) ?? 0) + n);
  }
  return out;
}

function group(src) {
  const s = decodeURIComponent(src).replace(/\\/g, "/").replace(/^.*?\[project\]\//, "").replace(/^webpack:\/\/\/?/, "");
  const nm = s.match(/node_modules\/((?:@[^/]+\/)?[^/]+)/);
  if (nm) return "npm:" + nm[1];
  if (perFile) return s.replace(/^.*?(src\/)/, "$1");
  const m =s.match(/(src\/[^/]+\/[^/]+(?:\/[^/]+)?)/);
  if (m) return m[1].replace(/\.[a-z]+$/, "");
  return s.split("/").slice(0, 3).join("/");
}

const kb = (n) => Math.round(n / 1024);
const result = {};
for (const route of routes) {
  const scripts = await scriptsOf(route);
  const decoded = scripts.reduce((t, s) => t + s.decoded, 0);
  const wire = scripts.reduce((t, s) => t + s.wire, 0);
  const first = scripts.filter((s) => s.first).reduce((t, s) => t + s.decoded, 0);
  result[route] = { files: scripts.length, decodedKB: kb(decoded), wireKB: kb(wire), firstKB: kb(first), scripts: scripts.map((s) => ({ file: s.url.replace(base, ""), decodedKB: kb(s.decoded), wireKB: kb(s.wire) })).sort((a, b) => b.decodedKB - a.decodedKB) };
  console.log(`${route}: ${scripts.length} files, ${kb(decoded)} KB decoded, ${kb(wire)} KB on the wire; ${kb(first)} KB named by the HTML`);
  if (withModules) {
    const total = new Map();
    for (const s of scripts) for (const [k, v] of await modulesOf(s.url)) total.set(k, (total.get(k) ?? 0) + v);
    const top = [...total].sort((a, b) => b[1] - a[1]).slice(0, perFile ? Infinity : 40).map(([k, v]) => (perFile ? { module: k, bytes: v } : { module: k, KB: kb(v) }));
    result[route].modules = top;
    if (!perFile) for (const t of top) console.log(`  ${String(t.KB).padStart(6)} KB  ${t.module}`);
  }
}
await browser.close();
if (jsonAt) writeFileSync(jsonAt, JSON.stringify(result, null, 2));
